async function withTimeout(fn, ms) {
  const c = new AbortController();
  const timer = setTimeout(() => c.abort(), ms);
  try {
    return await fn(c.signal);
  } finally {
    clearTimeout(timer); // never leak the timer
  }
}

async function enrichProduct(id) {
  const sources = {
    reviews: s => fetchReviews(id, { signal: s }),
    inventory: s => fetchInventory(id, { signal: s }),
    pricing: s => fetchPricing(id, { signal: s }),
  };
  const names = Object.keys(sources);
  const settled = await Promise.allSettled(
    names.map(n => withTimeout(sources[n], 800))
  );
  const data = {};
  settled.forEach((r, i) => {
    if (r.status === 'fulfilled') data[names[i]] = r.value;
    else log.warn(`enrich ${names[i]} failed`, r.reason); // logged, not swallowed
  });
  return data; // renders with whatever arrived
}

Why this meets the bar: allSettled runs all three in parallel and never rejects, so a single failure or 800ms timeout (an AbortError surfaced as a rejected reason) cannot lose the others. AbortController + a cleared timer bounds and cancels each call without leaking work. Every rejection is captured and logged, so nothing becomes an unhandledRejection that could crash the process. Use Promise.all here only if a missing source should fail the whole page, which the requirements say it should not.

