async function enrichProduct(id) {
  const sources = {
    reviews: s => fetchReviews(id, { signal: s }),
    inventory: s => fetchInventory(id, { signal: s }),
    pricing: s => fetchPricing(id, { signal: s }),
  };
  const names = Object.keys(sources);
  const settled = await Promise.allSettled(
    names.map(n => withTimeout(sources[n], 800))
  );
  const data = {};
  settled.forEach((r, i) => {
    if (r.status === 'fulfilled') data[names[i]] = r.value;
    else log.warn(`enrich ${names[i]} failed`, r.reason); // залогировано, не проглочено
  });
  return data; // рендерим с тем, что пришло
}

Почему это проходит планку: allSettled запускает все три параллельно и никогда не reject, поэтому единичное падение или таймаут 800 мс (AbortError всплывает как reason rejected) не теряет остальные. AbortController + очищенный таймер ограничивает и отменяет каждый вызов без утечки работы. Каждый rejection перехвачен и залогирован, поэтому ничто не становится unhandledRejection, который мог бы уронить процесс. Promise.all тут уместен, только если отсутствие источника должно ронять всю страницу — а требования говорят, что не должно.
